fun insertionSortDescending(arr: IntArray) {
    // نبدأ من العنصر الثاني لأن الأول يُعتبر مرتبًا
    for (i in 1 until arr.size) {
        val key = arr[i]
        var j = i - 1
        // ننقل العناصر الأصغر من المفتاح إلى اليمين
        while (j >= 0 && arr[j] < key) {
            arr[j + 1] = arr[j]
            j--
        }
        arr[j + 1] = key
        println("After pass $i: ${arr.joinToString()}")
    }
}

fun main() {
    val arr = intArrayOf(5, 2, 9, 1, 5, 6)
    println("Initial: ${arr.joinToString()}")
    insertionSortDescending(arr)
    println("Sorted: ${arr.joinToString()}")
}

