fun isPerfect(n: Int): Boolean {
    if (n < 2) return false
    var sum = 1
    // نفحص القواسم حتى الجذر التربيعي
    var i = 2
    while (i * i <= n) {
        if (n % i == 0) {
            sum += i
            if (i != n / i) sum += n / i
        }
        i++
    }
    return sum == n
}

fun main() {
    val limit = 10000
    val perfectNumbers = mutableListOf<Int>()
    for (num in 2..limit) {
        if (isPerfect(num)) perfectNumbers.add(num)
    }
    println("Perfect numbers up to $limit: ${perfectNumbers.joinToString(", ")}")
}

fun primeFactors(n: Int): List<Int> {
    var num = n
    val factors = mutableListOf<Int>()
    var divisor = 2
    // نستمر بالقسمة على الأعداد الصغيرة حتى نصل للجذر التربيعي
    while (divisor * divisor <= num) {
        while (num % divisor == 0) {
            factors.add(divisor)
            num /= divisor
        }
        divisor++
    }
    // إذا بقي عدد أكبر من 1 فهو عامل أولي
    if (num > 1) factors.add(num)
    return factors
}

fun main() {
    val n = 84
    val factors = primeFactors(n)
    println("Prime factors of $n: ${factors.joinToString(" * ")}")
}

