fun main() {
    // الشيفرة الوسيطة (bytecode) للتعبير (2 + 3) * 4
    val bytecode = listOf("push 2", "push 3", "add", "push 4", "mul")
    var decodeCount = 0

    fun decode(line: String): (MutableList<Int>) -> Unit {
        decodeCount++
        val parts = line.split(" ")
        return when (parts[0]) {
            "push" -> { s -> s.add(parts[1].toInt()) }
            "add" -> { s -> s.add(s.removeAt(s.size - 1) + s.removeAt(s.size - 1)) }
            else -> { s -> s.add(s.removeAt(s.size - 1) * s.removeAt(s.size - 1)) }
        }
    }

    val runs = 3
    var result = 0
    // التفسير: نفكّ ترميز كل سطر عند كل تشغيل
    repeat(runs) {
        val stack = mutableListOf<Int>()
        bytecode.forEach { line -> decode(line)(stack) }
        result = stack[0]
    }
    println("interpreted: result=$result decodes=$decodeCount")

    // AOT: نترجم مرة واحدة عند التثبيت ثم نشغّل النتيجة مرارًا
    decodeCount = 0
    val compiled = bytecode.map { line -> decode(line) }
    repeat(runs) {
        val stack = mutableListOf<Int>()
        compiled.forEach { op -> op(stack) }
        result = stack[0]
    }
    println("AOT: result=$result decodes=$decodeCount")
}

