class ViewHolder(val id: Int) { var text = "" }

class Adapter(private val data: List<String>) {
    var created = 0
    var bound = 0
    private val pool = mutableListOf<ViewHolder>()

    // onCreateViewHolder فقط عند فراغ المجمّع، ثم onBindViewHolder دائمًا
    fun obtain(pos: Int): ViewHolder {
        val vh = if (pool.isNotEmpty()) pool.removeAt(pool.size - 1) else ViewHolder(++created)
        vh.text = data[pos]
        bound++
        return vh
    }
    fun recycle(vh: ViewHolder) { pool.add(vh) }
}

fun main() {
    val data = (1..1000).map { "Item $it" }
    val adapter = Adapter(data)
    val visible = mutableListOf<ViewHolder>()
    for (pos in 0 until 5) visible.add(adapter.obtain(pos))   // أول شاشة

    for (pos in 5 until data.size) {                           // التمرير
        adapter.recycle(visible.removeAt(0))                   // خرج من الأعلى
        visible.add(adapter.obtain(pos))                       // يدخل من الأسفل
    }
    println("adapter items: ${data.size}")
    println("ViewHolders created: ${adapter.created}")
    println("onBind calls: ${adapter.bound}")
    println("on screen: " + visible.joinToString { it.text })
    println("holder ids: " + visible.map { it.id })
}

class SharedPrefs {
    private val data = mutableMapOf<String, Any>()

    fun getInt(key: String, def: Int): Int = data[key] as? Int ?: def
    fun getString(key: String, def: String): String = data[key] as? String ?: def
    fun edit(): Editor = Editor()

    // التعديلات تُجمَع في Editor ولا تُكتب إلا عند commit
    inner class Editor {
        private val pending = mutableMapOf<String, Any>()
        fun putInt(k: String, v: Int): Editor { pending[k] = v; return this }
        fun putString(k: String, v: String): Editor { pending[k] = v; return this }
        fun commit(): Boolean { data.putAll(pending); return true }
    }
}

fun main() {
    val prefs = SharedPrefs()
    println("launches=" + prefs.getInt("launches", 0))

    val editor = prefs.edit()
    editor.putInt("launches", 1).putString("theme", "dark")
    println("before commit: launches=${prefs.getInt("launches", 0)} theme=${prefs.getString("theme", "light")}")
    editor.commit()
    println("after commit: launches=${prefs.getInt("launches", 0)} theme=${prefs.getString("theme", "light")}")

    // الزيادة عند كل فتح للتطبيق: اقرأ ثم عدّل ثم احفظ
    prefs.edit().putInt("launches", prefs.getInt("launches", 0) + 1).commit()
    println("next launch: launches=" + prefs.getInt("launches", 0))
}

data class VNode(val tag: String, val text: String)

// تعريفية: الواجهة دالة في الحالة، لا أوامر رسم خطوة بخطوة
fun view(count: Int, items: List<String>): List<VNode> =
    listOf(VNode("h1", "Cart: $count")) + items.map { VNode("li", it) }

fun diff(old: List<VNode>, new: List<VNode>): List<String> {
    val patches = mutableListOf<String>()
    for (i in 0 until maxOf(old.size, new.size)) {
        val a = old.getOrNull(i)
        val b = new.getOrNull(i)
        when {
            a == null -> patches.add("CREATE ${b!!.tag}('${b.text}') at $i")
            b == null -> patches.add("REMOVE ${a.tag} at $i")
            a != b -> patches.add("UPDATE ${a.tag}[$i]: '${a.text}' -> '${b.text}'")
        }
    }
    return patches
}

fun main() {
    val v1 = view(1, listOf("Tea"))
    val v2 = view(2, listOf("Tea", "Coffee"))
    val patches = diff(v1, v2)     // فقط الفروق تصل إلى الشاشة الحقيقية
    patches.forEach { println(it) }
    println("full redraw: ${v2.size} nodes, patches: ${patches.size}")
}

sealed class El
data class Tag(val name: String, val children: List<El>) : El()
data class Txt(val s: String) : El()
data class Frag(val children: List<El>) : El()   // لا يُنتج وسمًا

fun render(e: El): String = when (e) {
    is Txt -> e.s
    is Tag -> "<" + e.name + ">" + e.children.joinToString("") { render(it) } + "</" + e.name + ">"
    is Frag -> e.children.joinToString("") { render(it) }
}

fun nodes(e: El): Int = when (e) {
    is Txt -> 0
    is Tag -> 1 + e.children.sumBy { nodes(it) }
    is Frag -> e.children.sumBy { nodes(it) }
}

// مكوّنان قابلان لإعادة الاستخدام: الأول بـFragment والثاني بغلاف div
fun rowFrag(k: String, v: String): El = Frag(listOf(Tag("dt", listOf(Txt(k))), Tag("dd", listOf(Txt(v)))))
fun rowDiv(k: String, v: String): El = Tag("div", listOf(rowFrag(k, v)))

fun main() {
    val fields = listOf("Name" to "Sara", "Age" to "21")
    fun page(row: (String, String) -> El): El =
        Tag("div", listOf(Tag("h1", listOf(Txt("Hello, Sara"))), Tag("dl", fields.map { row(it.first, it.second) })))

    println(render(page(::rowFrag)))
    println("nodes with Fragment: " + nodes(page(::rowFrag)))
    println("nodes with wrapper div: " + nodes(page(::rowDiv)))
}

