class ScoreComponent(private var props: Map<String, Int>) {
    var renders = 0

    // لا نعيد الرسم إلا إذا تغيّرت الخاصية التي يعتمد عليها العرض
    private fun shouldComponentUpdate(next: Map<String, Int>) = next["score"] != props["score"]

    private fun render() {
        renders++
        println("render score=${props["score"]}")
    }

    fun mount() {
        println("constructor")
        render()
        println("componentDidMount: start timer")
    }

    fun update(next: Map<String, Int>) {
        val rerender = shouldComponentUpdate(next)
        props = next                        // الخصائص تُحدَّث دائمًا
        if (!rerender) {
            println("shouldComponentUpdate=false, skip render")
            return
        }
        render()
        println("componentDidUpdate")
    }

    fun unmount() = println("componentWillUnmount: clear timer")   // تجنّب تسرّب الذاكرة
}

fun main() {
    val c = ScoreComponent(mapOf("score" to 1, "level" to 1))
    c.mount()
    c.update(mapOf("score" to 1, "level" to 2))   // تغيّر غير مؤثر
    c.update(mapOf("score" to 2, "level" to 2))
    c.unmount()
    println("renders=" + c.renders)
}

fun main() {
    // الاستيرادات: من يعتمد على من
    val deps = mapOf(
        "App.js" to listOf("Home.js", "Header.js"),
        "Home.js" to listOf("api.js", "Header.js"),
        "Header.js" to listOf("theme.js"),
        "api.js" to emptyList<String>(),
        "theme.js" to emptyList<String>(),
        "Unused.js" to emptyList<String>()
    )
    val sizeKb = mapOf("App.js" to 3, "Home.js" to 5, "Header.js" to 2,
        "api.js" to 4, "theme.js" to 1, "Unused.js" to 9)

    val seen = mutableSetOf<String>()
    val order = mutableListOf<String>()
    // الاعتماديات أولًا ثم الملف نفسه، ولا نزور الملف مرتين
    fun visit(file: String) {
        if (!seen.add(file)) return
        deps.getValue(file).forEach { visit(it) }
        order.add(file)
    }
    visit("App.js")

    println("bundle order: " + order.joinToString(", "))
    println("skipped: " + (deps.keys - seen).joinToString(", "))
    println("bundle size: ${order.sumBy { sizeKb.getValue(it) }} KB of ${sizeKb.values.sum()} KB")
}

data class Item(val name: String, val flex: Int = 0, val fixed: Int = 0)

fun layoutRow(width: Int, items: List<Item>): List<Pair<String, Int>> {
    val free = width - items.sumBy { it.fixed }     // المساحة المتبقية بعد العناصر الثابتة
    val totalFlex = items.sumBy { it.flex }
    return items.map { it.name to (if (it.flex > 0) free * it.flex / totalFlex else it.fixed) }
}

fun main() {
    val row = listOf(Item("icon", fixed = 60), Item("title", flex = 2), Item("a", flex = 1), Item("b", flex = 1))
    // نفس التخطيط، عرضان مختلفان: الأيقونة ثابتة والبقية تتمدد بنسبها
    for ((label, w) in listOf("portrait" to 360, "landscape" to 640)) {
        val sizes = layoutRow(w, row)
        println("$label($w): " + sizes.joinToString { it.first + "=" + it.second } + " sum=" + sizes.sumBy { it.second })
    }
}

typealias Fix = Pair<Double, Double>

class FakeGps {
    private val fixes = listOf(24.7136 to 46.6753, 24.7140 to 46.6760, 24.7150 to 46.6770, 24.7165 to 46.6785)
    private val watchers = mutableMapOf<Int, (Fix) -> Unit>()
    private var nextId = 1

    fun getCurrentPosition(cb: (Fix) -> Unit) = cb(fixes[0])        // مرة واحدة
    fun watchPosition(cb: (Fix) -> Unit): Int { watchers[nextId] = cb; return nextId++ }
    fun clearWatch(id: Int) { watchers.remove(id) }
    fun listeners() = watchers.size
    fun tick(i: Int) = watchers.values.toList().forEach { it(fixes[i]) }
}

fun meters(a: Fix, b: Fix): Double {
    val p1 = Math.toRadians(a.first); val p2 = Math.toRadians(b.first)
    val dp = p2 - p1; val dl = Math.toRadians(b.second - a.second)
    val h = Math.sin(dp / 2) * Math.sin(dp / 2) + Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) * Math.sin(dl / 2)
    return 2 * 6371000.0 * Math.asin(Math.sqrt(h))
}

fun main() {
    val gps = FakeGps()
    gps.getCurrentPosition { println("one-shot: %.4f,%.4f".format(it.first, it.second)) }

    var total = 0.0
    var last: Fix? = null
    val id = gps.watchPosition { p ->
        val prev = last
        if (prev != null) total += meters(prev, p)
        last = p
        println("watch: %.4f,%.4f total=%dm".format(p.first, p.second, total.toInt()))
    }
    for (i in 0..2) gps.tick(i)
    gps.clearWatch(id)          // أوقف المراقبة لتوفير البطارية
    gps.tick(3)                 // لا أحد يسمع هذا التحديث
    println("listeners=" + gps.listeners())
}
